const $=id=>document.getElementById(id), money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v), num=v=>Math.round(v).toLocaleString('en-US');
let state={...defaults},metrics,alternatives=[],yaw=-.65,zoom=1,wireframe=false,studies=[];
