const groups={geometryControls:['span','aspect','floors','height','taper','twist'],constraintControls:['core','common','site','maxHeight','frontage'],rentControls:['rent','premium','occupancy','reserve']};
function controlValue(k){return `${Math.round(state[k]*100)/100}${schema[k][4]?' '+schema[k][4]:''}`}
for(const [group,keys] of Object.entries(groups))for(const k of keys){const [label,min,max,step]=schema[k];let div=document.createElement('div');div.className='control';div.innerHTML=`<div class="controlhead"><label for="${k}">${label}</label><output id="${k}Value" for="${k}">${controlValue(k)}</output></div><input type="range" id="${k}" min="${min}" max="${max}" step="${step}" value="${state[k]}">`;$(group).append(div);$(k).addEventListener('input',()=>{state[k]=Number($(k).value);changed()})}
