function sync(){for(const k of Object.keys(schema)){if(k==='span'){$(k).min=Math.min(schema[k][1],state[k]);$(k).max=Math.max(schema[k][2],state[k])}$(k).value=state[k];$(k+'Value').textContent=controlValue(k)}$('family').value=state.family;$('skin').value=state.skin}
